

CREATE TABLE `business_units` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `BUCode` varchar(15) NOT NULL,
  `BUName` varchar(100) NOT NULL,
  `fldDepartment` varchar(50) NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `dispatch_history` (
  `fldID` int(50) NOT NULL AUTO_INCREMENT,
  `fldInputDate` date NOT NULL,
  `fldEmployeeNumber` int(10) NOT NULL,
  `fldStartDate` date NOT NULL,
  `fldEndDate` date NOT NULL,
  `fldBU` varchar(50) NOT NULL,
  `fldProject` varchar(50) NOT NULL,
  `fldOrder` varchar(100) NOT NULL DEFAULT '-',
  `fldCountry` varchar(20) NOT NULL,
  `fldDepartment` varchar(50) NOT NULL,
  `fldReport` varchar(100) NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=1312 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `emp_certs` (
  `fldID` int(10) NOT NULL AUTO_INCREMENT,
  `fldEmployeeNum` int(10) NOT NULL,
  `fldCert` varchar(100) NOT NULL,
  `fldLevel` varchar(100) NOT NULL,
  `fldDateReceived` date NOT NULL,
  `fldCertFile` varchar(100) NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `emp_login` (
  `fldID` int(20) NOT NULL AUTO_INCREMENT,
  `fldEmployeeNum` int(50) NOT NULL,
  `fldName` varchar(100) NOT NULL,
  `fldUser` varchar(20) NOT NULL,
  `fldPC` varchar(20) NOT NULL,
  `fldGroup` varchar(50) NOT NULL,
  `fldDesig` varchar(50) NOT NULL,
  `fldAccess` int(2) NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=198 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `emp_prof` (
  `fldID` int(20) NOT NULL AUTO_INCREMENT,
  `fldEmployeeNum` int(50) NOT NULL,
  `fldName` varchar(100) NOT NULL,
  `fldSurname` varchar(100) NOT NULL,
  `fldFirstname` varchar(100) NOT NULL,
  `fldNick` varchar(50) NOT NULL,
  `fldUser` varchar(20) NOT NULL,
  `fldGroup` varchar(50) NOT NULL,
  `fldGroups` varchar(100) NOT NULL,
  `fldDesig` varchar(50) NOT NULL,
  `fldBirthDate` date DEFAULT NULL,
  `fldGender` varchar(1) NOT NULL DEFAULT 'M',
  `fldStatus` varchar(20) NOT NULL,
  `fldDateHired` date DEFAULT NULL,
  `fldLotus` varchar(50) NOT NULL,
  `fldPic` varchar(100) NOT NULL,
  `fldOthers` double(10,1) NOT NULL DEFAULT 0.0,
  `fldStartTime` varchar(100) NOT NULL,
  `fldMOT` varchar(100) NOT NULL,
  `fldRemarks` varchar(100) NOT NULL,
  `fldUnit` varchar(100) NOT NULL,
  `fldHouse` varchar(100) NOT NULL,
  `fldStreet` varchar(100) NOT NULL,
  `fldSub` varchar(100) NOT NULL,
  `fldBrgy` varchar(100) NOT NULL,
  `fldCity` varchar(100) NOT NULL,
  `fldProv` varchar(100) NOT NULL,
  `fldZip` int(4) DEFAULT NULL,
  `fldDesigStamp` varchar(100) NOT NULL,
  `fldGroupStamp` varchar(100) NOT NULL,
  `fldActiveStamp` varchar(100) NOT NULL,
  `fldStampDate` date DEFAULT NULL,
  `fldChecker` varchar(100) NOT NULL,
  `fldActive` int(1) NOT NULL DEFAULT 1,
  `fldUpload` int(1) NOT NULL DEFAULT 0,
  `fldAccess` int(1) NOT NULL,
  `fldAccessCommute` int(1) NOT NULL,
  `fldMRRSReserve` int(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=242 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `emp_profile` (
  `fldID` int(50) NOT NULL AUTO_INCREMENT,
  `fldName` varchar(100) NOT NULL,
  `fldEmployeeNumber` int(10) NOT NULL,
  `fldUsername` varchar(20) NOT NULL,
  `fldBirthDate` date NOT NULL,
  `fldStatus` varchar(20) NOT NULL,
  `fldDateHired` date NOT NULL,
  `fldPosition` varchar(50) NOT NULL,
  `fldGroup` varchar(50) NOT NULL,
  `fldLotus` varchar(50) NOT NULL,
  `fldPic` varchar(100) NOT NULL,
  `fldOthers` double NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `entry_logs` (
  `fldID` int(20) NOT NULL AUTO_INCREMENT,
  `fldEmployeeNum` int(50) NOT NULL,
  `fldDesigStamp` varchar(100) NOT NULL,
  `fldGroupStamp` varchar(100) NOT NULL,
  `fldActiveStamp` varchar(100) NOT NULL,
  `fldStampDate` date DEFAULT NULL,
  `fldChecker` varchar(100) NOT NULL,
  `fldGHCountStamp` int(10) NOT NULL,
  `fldJHCountStamp` int(10) NOT NULL,
  `fldDHCountStamp` int(10) NOT NULL,
  `fldTHCountStamp` int(10) NOT NULL,
  `fldEDateStamp` date DEFAULT NULL,
  `fldEChecker` varchar(100) NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=242 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `group_history` (
  `fldID` int(50) NOT NULL AUTO_INCREMENT,
  `fldEmployeeNumber` int(10) NOT NULL,
  `fldStartDate` date NOT NULL,
  `fldEvent` varchar(20) NOT NULL,
  `fldLocation` varchar(50) NOT NULL,
  `fldGroupName` varchar(50) NOT NULL,
  `fldPosition` varchar(50) NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=1579 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `jh_selection` (
  `fldID` int(50) NOT NULL AUTO_INCREMENT,
  `fldBU` varchar(50) NOT NULL,
  `fldProj` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fldOrder` varchar(50) NOT NULL,
  `fldCountry` varchar(50) NOT NULL,
  `fldProduct` varchar(100) NOT NULL,
  `fldBUIC` varchar(50) NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=850 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `job_history` (
  `fldID` int(50) NOT NULL AUTO_INCREMENT,
  `fldInputDate` date NOT NULL DEFAULT current_timestamp(),
  `fldEmployeeNumber` int(10) NOT NULL,
  `fldStartDate` date NOT NULL,
  `fldEndDate` date NOT NULL,
  `fldBU` varchar(50) NOT NULL,
  `fldProject` varchar(50) NOT NULL,
  `fldOrder` varchar(50) NOT NULL DEFAULT '-',
  `fldCountry` varchar(20) NOT NULL,
  `fldProduct` varchar(100) NOT NULL,
  `fldBUIC` varchar(50) NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=1528 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `kdtpositions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fldAcro` varchar(5) NOT NULL,
