) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `phlocation` (
  `fldID` int(10) NOT NULL AUTO_INCREMENT,
  `fldProv` varchar(100) NOT NULL,
  `fldCity` varchar(100) NOT NULL,
  `fldBrgy` varchar(100) NOT NULL,
  PRIMARY KEY (`fldID`)
) ENGINE=InnoDB AUTO_INCREMENT=8831 DEFAULT CHARSET=utf8mb4;






CREATE TABLE `photo_gallery` (
  `fldID` int(50) NOT NULL AUTO_INCREMENT,
  `fldEmployeeNum` int(10) NOT NULL,
  `fldDate` date NOT NULL,
